SourceCode.Declaration:
/// <summary>
/// Data contract class used to pass an ItemId from a UI/controller to a processing service.
/// </summary>
/// <remarks>
/// This class is intended for lightweight transfer of the ItemId value. The method parmItemId
/// is annotated with DataMemberAttribute so frameworks that rely on data contract serialization
/// will include the value.
/// </remarks>
[DataContractAttribute]
final class AVAItemOpenSalesAmountContract
{
    /// <summary>
    /// Backing field that stores the ItemId value supplied by the caller.
    /// </summary>
    ItemId itemId;

}

Method.Source:
/// <summary>
/// Data member used to pass ItemId from the dialog/controller to the service.
/// </summary>
/// <param name="_itemId">
/// Optional ItemId to set on the contract. When omitted, the current stored value is returned.
/// </param>
/// <returns>The ItemId currently stored in the contract.</returns>
[DataMemberAttribute('itemId')]
public ItemId parmItemId(ItemId _itemId = itemId)
{
    itemId = _itemId;
    return itemId;
}
